script:
Create Variable U V Radius Cost Keep;
U=0;
V=0;
Radius=7000;
Cost=0;
Keep=41;
Create Spacecraft Sat;
Sat.DateFormat=UTCGregorian;
Sat.Epoch='01 Jan 2000 12:00:00.000';
Sat.CoordinateSystem=EarthMJ2000Eq;
Sat.DisplayStateType=Cartesian;
Sat.X=7000;
Sat.Y=0;
Sat.Z=0;
Sat.VX=0;
Sat.VY=7.5460532872678359;
Sat.VZ=0;
Create ForceModel FM;
FM.PrimaryBodies={};
FM.PointMasses={Earth};
FM.Drag=None;
FM.SRP=Off;
Create Propagator PropA;
PropA.FM=FM;
PropA.InitialStepSize=5;
PropA.MinStep=5;
PropA.MaxStep=5;
PropA.Accuracy=1e-12;
Create DifferentialCorrector DC Inner;
DC.MaximumIterations=30;
Inner.MaximumIterations=30;
DC.ReportFile='@WORK@/dc.txt';
Inner.ReportFile='@WORK@/inner.txt';
Create Yukon Opt;
Opt.MaximumIterations=50;
Opt.FeasibilityTolerance=1e-12;
Opt.OptimalityTolerance=1e-12;
Opt.FunctionTolerance=1e-12;
Opt.UseCentralDifferences=true;
Opt.ReportFile='@WORK@/opt.txt';
Create ReportFile Trials;
Trials.Filename='@WORK@/Trials.csv';
Trials.WriteHeaders=false;
Trials.FixedWidth=false;
Trials.Delimiter=',';
Trials.Precision=17;
Trials.SolverIterations=All;
Create EphemerisFile Export;
Export.Spacecraft=Sat;
Export.FileFormat=CCSDS-OEM;
Export.Filename='@WORK@/Final only Δ.oem';
Export.CoordinateSystem=EarthMJ2000Eq;
Export.StepSize=IntegratorSteps;
Export.InterpolationOrder=7;
Export.WriteEphemeris=true;
BeginMissionSequence;
Report 'Arm' Trials Keep;
Optimize 'Final solution only' Opt {SolveMode = Solve, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary Opt(U = 0, {Perturbation = 0.0001, Lower = -2, Upper = 4, MaxStep = 1});
Target 'Inner solve' Inner {SolveMode = Solve, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary Inner(V = 0, {Perturbation = 0.0001, Lower = -2, Upper = 5, MaxStep = 2});
Radius = 7000 + 100*U + 10*V;
Sat.X = Radius;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = sqrt(398600.4415/Radius);
Sat.VZ = 0;
Report 'Pass enter' Trials U V;
Propagate 'Trial or final circle' PropA(Sat) {Sat.ElapsedSecs = 120};
Report 'Pass state' Trials U V Sat.ElapsedSecs Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ;
If V > 2.999;
Stop;
EndIf;
Achieve Inner(V = 3, {Tolerance = 0.0000000001});
EndTarget;
Cost = (U-2)^2;
Minimize Opt(Cost);
EndOptimize;
Keep=99;
Report 'Done' Trials Keep;

